SELECT
    rf.ID AS rich_filter_id,
    rf.NAME AS rich_filter_name,
    jf.id AS jira_filter_id,
    jf.filtername AS jira_filter_name,
    jf.authorname AS jira_filter_owner,
    jf.reqcontent AS jira_filter_jql
FROM `AO_24D977_QRFRFE0` rf
INNER JOIN searchrequest jf ON rf.JIRA_FILTER_ID = jf.id
WHERE (
    -- project = KEY 형태 매칭
    jf.reqcontent REGEXP 'project[[:space:]]*=[[:space:]]*(AAMSW|ACQT|ACQT2|ACQT3|AIAGENT|AODCS|ASST|BDD|BMSRSEV|BMSRSEVMST|C0207AICC|CARLIFE|CSMR|CTDTASK|DPMS|EFOREST|EPSD|EPSDV|ETD|EVSPTO|GA|GQCB|GQHR|GW|HACSDEV|HAELA|HBMS|HCLOUDREQU|HCRMHUB|HDOTPRD001|HETDA|HEVENT|HKMCKMS|HMCIBAT|HMCSA|HMETCEUOTA|HMGMA0TRA|HMGMAACS|HMGPR|HMIECPD|HMIEECD|HMJIM|HMJSOP|HMJVR|HMTCPASS01|HTWO|INBF|INCIDENT|INCSMS|INTPT|JIDW|KEP|KIACPO|KIAPIMS|KIAVIK|KNGCCBT|LLX3CCU2|MCAS|MECMS|MEEI|MEHM|MEVS|MRP|MYG|NBRNDPRJ|P231789|PLAN1FEB|PM00|QDHR|ROBS|SAMSV4|SDFACS|SDT|SMEFORK|SMELEARN|SPQT|SWQR|TECHSTRAT|TJNA|TJUCJ01|TQAG|UISP|UPPR|VAIPCTL|VAISIHMI|VCSQ|WEISS|WHD|YCHB|YNAQ|YNKP|YNSQ|YSAA|YSAB|YSAH|YSEC)'

    -- project IN (KEY1, KEY2...) 형태 매칭
    OR jf.reqcontent REGEXP 'project[[:space:]]+in[[:space:]]*\\([^)]*(AAMSW|ACQT|ACQT2|ACQT3|AIAGENT|AODCS|ASST|BDD|BMSRSEV|BMSRSEVMST|C0207AICC|CARLIFE|CSMR|CTDTASK|DPMS|EFOREST|EPSD|EPSDV|ETD|EVSPTO|GA|GQCB|GQHR|GW|HACSDEV|HAELA|HBMS|HCLOUDREQU|HCRMHUB|HDOTPRD001|HETDA|HEVENT|HKMCKMS|HMCIBAT|HMCSA|HMETCEUOTA|HMGMA0TRA|HMGMAACS|HMGPR|HMIECPD|HMIEECD|HMJIM|HMJSOP|HMJVR|HMTCPASS01|HTWO|INBF|INCIDENT|INCSMS|INTPT|JIDW|KEP|KIACPO|KIAPIMS|KIAVIK|KNGCCBT|LLX3CCU2|MCAS|MECMS|MEEI|MEHM|MEVS|MRP|MYG|NBRNDPRJ|P231789|PLAN1FEB|PM00|QDHR|ROBS|SAMSV4|SDFACS|SDT|SMEFORK|SMELEARN|SPQT|SWQR|TECHSTRAT|TJNA|TJUCJ01|TQAG|UISP|UPPR|VAIPCTL|VAISIHMI|VCSQ|WEISS|WHD|YCHB|YNAQ|YNKP|YNSQ|YSAA|YSAB|YSAH|YSEC)[^)]*\\)'
)
ORDER BY jira_filter_id, rich_filter_id;
